### [234. 回文链表](https://leetcode.cn/problems/palindrome-linked-list/)
用**快慢指针**找到中点，把**后半段反转**，然后从头和中点同时遍历比较是否相同。
```java
class Solution {
    public boolean isPalindrome(ListNode head) {
        ListNode fast = head;
        ListNode slow = head;
        while(fast != null && fast.next != null){
            fast = fast.next.next;
            slow = slow.next;
        }
        ListNode secondList = reverseList(slow);
        // 保存头结点用于恢复
        ListNode copysecondList = secondList;
        fast = head;
        while(secondList != null){
            if(fast.val != secondList.val)
            {
                reverseList(copysecondList);
                return false;
            }
            fast = fast.next;
            secondList = secondList.next;
        }
        // 恢复链表（关键加分点）
        reverseList(copysecondList);
        return true;
    }
    public ListNode reverseList(ListNode node){
        ListNode pre = null;
        while(node != null){
            ListNode next = node.next;
            node.next = pre;
            pre = node;
            node = next;
        }
        return pre;
    }
}
```

``` java
import java.util.*;

public class Main{
    private static class Node{
        int val;
        Node next;
        Node(int val){
            this.val = val;
            this.next = null;
        }
    }

    private static boolean isPalindrome(Node head){
        if(head == null){
            return true;
        }
        Node fast = head;
        Node slow = head;
        while(fast != null && fast.next != null){
            fast = fast.next.next;
            slow = slow.next;
        }
        fast = head;
        slow = reverse(slow);
        Node copyNode = slow;
        while(slow != null){
	        // 比较节点值
            if(slow.val != fast.val){
                return false;
            }
            slow = slow.next;
            fast = fast.next;
        }
        reverse(copyNode);
        return true;
    }
    
    private static Node reverse(Node node){
        Node pre = null;
        while(node != null){
            Node next = node.next;
            node.next = pre;
            pre = node;
            node = next;
        }
        return pre;
    }
    
    public static void main(String[] args){
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        Node dummy = new Node(0);
        Node cur = dummy;
        for(int i=0; i<n; ++i){
            cur.next = new Node(sc.nextInt());
            cur = cur.next;
        }
        System.out.println(isPalindrome(dummy.next));
    }
}
