#### 并查集
向上指的图

需求：{a},{b},{c},{d},{e},现在的功能需求是boolen:issameset（a,b），和void union(a,b)，第一个是判断是否是**属于同一个集合**，第二个是把两个元素的**集合合并**。
如果使用链表，那么合并很快，但是判断是否相同很麻烦，
如果使用hashset，判断是否相同很快，但是合并也不是O(1)，因此需要并查集。

思路：每个元素先指向自己。判断两个元素是否属于同一个集合时，比较它们最终找到的根节点；合并时，让**规模较小集合的根节点**直接**指向规模较大集合的根节点**。

优化：当判断是否是同一集合的过程中，会不断往上找，在找完之后，将**沿途的父节点**指向直接修改成指向**根节点**。

并查集时间复杂度是随着getHead函数调用次数逼近O(N)时，单次代价可以认为是O(1)的。
```java
import java.util.HashMap;
import java.util.List;
import java.util.Stack;

public class UnionFind {
    public static class Element<V> {
        public V value;

        public Element(V value) {
            this.value = value;
        }

    }

    public static class UnionFindSet<V> {
        //给一个V  得一一对应加工出来的元素
        public HashMap<V, Element<V>> elementMap;

        //key代表一个节点  value代表它的父节点
        public HashMap<Element<V>, Element<V>> fatherMap;

        //key代表这个小集合的根节点（代表结点）  value代表它的size
        public HashMap<Element<V>, Integer> rankMap;

        public UnionFindSet(List<V> list) {
            elementMap = new HashMap<>();
            fatherMap = new HashMap<>();
            rankMap = new HashMap<>();
            for (V value : list) {
                Element<V> element = new Element<V>(value);
                elementMap.put(value, element);
                fatherMap.put(element, element);
                rankMap.put(element, 1);
            }
        }

        private Element<V> findHead(Element<V> element) {
            Stack<Element<V>> path = new Stack<>();
            while (element != fatherMap.get(element)) {
                path.push(element);
                element = fatherMap.get(element);
            }
            while (!path.isEmpty()) {
                fatherMap.put(path.pop(), element);
            }
            return element;
        }

        public boolean isSameSet(V a, V b) {
            //并查集使用的前提是有初始化
            if (elementMap.containsKey(a) && elementMap.containsKey(b)) {
                return findHead(elementMap.get(a)) == findHead(elementMap.get(b));
            }
            return false;
        }

        public void union(V a, V b) {
            if (elementMap.containsKey(a) && elementMap.containsKey(b)) {
                Element<V> aF = findHead(elementMap.get(a));
                Element<V> bF = findHead(elementMap.get(b));
                if (aF != bF) {
                    Element<V> big = rankMap.get(aF) >= rankMap.get(bF) ? aF : bF;
                    Element<V> small = big == aF ? bF : aF;
                    fatherMap.put(small, big);
                    rankMap.put(big, rankMap.get(aF) + rankMap.get(bF));
                    rankMap.remove(small);
                }
            }
        }

    }
}
```

