class Solution {
    public String longestPalindrome(String s) {
        char[] cs = new char[s.length()*2+1];
        for(int i = 0; i < s.length()*2+1; ++i){
            if(i%2 == 0)
                cs[i] = '#';
            else
	            // 这里应该是i/2，没有+1，应为1 -》 0
                cs[i] = s.charAt(i/2);
        }
		//回文中心
        int c = -1;
        //回文右边界的再往右一个位置，最右的有效区是R-1位置
        int r = -1;
        int[] pArr = new int[s.length()*2+1];
        int max = Integer.MIN_VALUE;
        int maxId = -1

        for(int i = 0; i < s.length()*2+1; ++i){
	        // i至少的回文区域
            int passNum = r>i ? Math.min(pArr[2*c-i], r-i) : 1;
            int j = 0;
            // 不越界
            while(i-passNum-j>=0 && i+passNum+j<(s.length()*2+1)){
                if(cs[i-passNum-j] == cs[i+passNum+j]){
                    ++j;
                }else{
                    break;
                }
            }
            if(i+passNum+j > r){
                r = i+passNum+j;
                c = i;
            }
            pArr[i] = passNum+j;
            if(pArr[i] > max){
                max = pArr[i];
                maxId = i;
            }
        }
        StringBuffer sOut = new StringBuffer();
        for(int i = maxId-pArr[maxId]+1; i <= maxId+pArr[maxId]-1; ++i){
            if(cs[i] != '#'){
                sOut.append(cs[i]);
            }
        }
        return sOut.toString();
    }
}

```
