### 复制带有随机指针的链表 LCR154

分为三步拷贝
```java
class Solution {
    public Node copyRandomList(Node head) {
        if (head == null) return null;

        Node cur = head;

        // 1. 在每个原节点后面插入拷贝节点
        while (cur != null) {
            Node copy = new Node(cur.val);
            Node temp = cur.next;
            cur.next = copy;
            copy.next = temp;
            cur = temp;
        }

        // 2. 设置拷贝节点的 random
        cur = head;
        while (cur != null) {
            if (cur.random != null) {
                cur.next.random = cur.random.next;
            }
            cur = cur.next.next;
        }

        // 3. 拆分原链表和拷贝链表
        cur = head;
        Node copyHead = head.next;

        while (cur != null) {
            Node copy = cur.next;
            cur.next = copy.next;  // 恢复原链表

            if (copy.next != null) {
                copy.next = copy.next.next;  // 串起拷贝链表
            }

            cur = cur.next;
        }

        return copyHead;
    }
}
```

