class Solution {
    public List<Integer> preorderTraversal(TreeNode root) {
        List<Integer> vec = new ArrayList();
        traversal(root, vec);
        return vec;
    }
    public void traversal(TreeNode root, List<Integer> vec){
        if(root == null)
            return;
        vec.add(root.val);
        if(root.left != null)
        traversal(root.left, vec);
        if(root.right != null)
        traversal(root.right, vec);
