public class getSuccessorNode {
    public static class TreeNode {
        int val = 0;
        TreeNode left = null;
        TreeNode right = null;
        TreeNode parent = null;

        public TreeNode(int val) {
            this.val = val;
        }
    }

    public static TreeNode getSuccessorNode1(TreeNode pNode) {
        if (pNode == null) {
            return null;
        }

        if (pNode.right != null) {
		    // 以第一个右孩子开始看左节点
            TreeNode cur = pNode.right;
            while (cur.left != null) {
                cur = cur.left;
            }
            return cur;
        } else {
            TreeNode cur = pNode;
            // right与自己对比
            while (cur.parent != null && cur.parent.right == cur) {
                cur = cur.parent;
            }
            return cur.parent;
        }
    }
}
