#### 208. 实现 Trie (前缀树)
每个节点代表一个字符  
从根到某节点路径 = 一个前缀

查询有没有某个字符串，hashset也可以做，但是以某个字符串为前缀的功能就完成不了了，前缀树就可以。如果next的种类特别多，可以用hashset。
![算法笔记配图](/image/algorithms/pasted-image-20260511155555.png)

```java
	public static class Trie {

		public static class TrieNode {
			public int path;// 这个节点被通过了多少次
			public int end;// 它是多少个字符串的结尾节点
			public TrieNode[] nexts;// 它的下一个节点
			public TrieNode() {
				path = 0;
				end = 0;
				// 这里没有括号
				nexts = new TrieNode[26];
			}
		}

		private TrieNode root;
		public Trie() {
			root = new TrieNode();
		}
		//添加新词
		public void insert(String word) {
			if (word == null) {
				return;
			}
			// 字符串变为字符数组
			char[] chs = word.toCharArray();
			TrieNode node = root;
			node.path++;
			int index = 0;
			for (int i = 0; i < chs.length; i++) {// 遍历字符
				index = chs[i] - 'a';// 计算当前字符属于0-25哪条路径
				if (node.nexts[index] == null) {//没有路径就新建路径
					node.nexts[index] = new TrieNode();
				}
				// node变为路径上的下一个节点
				node = node.nexts[index];
				node.path++;
			}
			// 这里node已经是最后一个节点,不需要node.nexts[index].end
			node.end++;
		}

		public void delete(String word) {
			// 如果加入过这个词，才做删除
			if (search(word) != 0) {
				char[] chs = word.toCharArray();
				TrieNode node = root;
				int index = 0;
				for (int i = 0; i < chs.length; i++) {
					index = chs[i] - 'a';
					// 如果在删除路径的过程中，遇到path为0了，后续路径
					// 可以直接丢弃
					if (--node.nexts[index].path == 0) {
						node.nexts[index] = null;
						return;
					}
					node = node.nexts[index];
				}
				node.end--;
			}
		}

		public int search(String word) {
			if (word == null) {
				return 0;
			}
			char[] chs = word.toCharArray();
			TrieNode node = root;
			int index = 0;
			for (int i = 0; i < chs.length; i++) {
				index = chs[i] - 'a';
				//到节点末端都没找到，就是加入了0次
				if (node.nexts[index] == null) {
					return 0;
				}
				node = node.nexts[index];
			}
			return node.end;
		}
		// 有多少哥词以pre为前缀
		public int prefixNumber(String pre) {
			if (pre == null) {
				return 0;
			}
			char[] chs = pre.toCharArray();
			TrieNode node = root;
			int index = 0;
			for (int i = 0; i < chs.length; i++) {
				index = chs[i] - 'a';
				if (node.nexts[index] == null) {
					return 0;
				}
				node = node.nexts[index];
			}
			return node.path;
		}
	}

