#### 677. 键值映射

多维护一个HashMap, 在插入前先看map里有没有这个键值对, 有的话就是覆盖,没有的话就是+

```java
class MapSum {

    public class mapNode{
        public int sum;
        public mapNode[] nexts;

        public mapNode(){
            sum = 0;
            nexts = new mapNode[26];
        }
    }

    private mapNode mapRoot;
    private HashMap<String, Integer> map;
    public MapSum() {
        mapRoot = new mapNode();
        map = new HashMap<>();
    }

    public void insert(String key, int val) {
        if(key == null)
            return ;
        int old = map.getOrDefault(key, 0);
        int det = val - old;
        mapNode node = mapRoot;
        int index = 0;
        char[] s = key.toCharArray();
        for (char c : s){
            index = c - 'a';
            if(node.nexts[index] == null){
                node.nexts[index] = new mapNode();
            }
            node = node.nexts[index];
            node.sum += det;
        }
        // map中应该放真实的值 val
        map.put(key, val);
    }

    public int sum(String prefix) {
        if(prefix == null)
            return 0;
        mapNode node = mapRoot;
        int index = 0;
        char[] s = prefix.toCharArray();
        for (char c : s){
            index = c - 'a';
            if(node.nexts[index] == null){
                return 0;
            }
            node = node.nexts[index];
        }
        return node.sum;
    }
}

