    public int eraseOverlapIntervals(int[][] intervals) {
        if(intervals == null)
            return 0;
        // sort 在返回值为负时,第一个值在前
        Arrays.sort(intervals, (a,b)->Integer.compare(a[1], b[1]));
        int end = intervals[0][1];
        int ans = 1;
        for(int[] i:intervals){
            if(end <= i[0]){
                end = i[1];
                ++ ans;
            }
        }
        return intervals.length-ans;
    }
