class Solution {
    List<List<Integer>> ans = new ArrayList<>();
    public List<List<Integer>> permute(int[] nums) {
        process(nums, 0);
        return ans;
    }
    public void process(int[] nums, int i){
        if(i == nums.length){
            List<Integer> cur = new ArrayList<>();
            for(Integer num:nums){
                cur.add(num);
            }
            ans.add(cur);
            return ;
        }
        // 无法拷贝，这是指向
        // int[] temp = nums;
        // 拷贝  int[] temp = nums.clone();-----低效
        for(int j = i; j < nums.length; ++j){
            int num = nums[j];
            nums[j] = nums[i];
            nums[i] = num;
            process(nums, i+1);
            // 原地撤销
            num = nums[i];
            nums[i] = nums[j];
            nums[j] = num;
        }
    }
}
